# -*- coding: utf-8 -*-
"""Import owner Excel planning data into PlanProduction (idempotent).
Sources: EOY PLANNING LUKASZ.xlsx + TEST PLANNING 2026 - 23 november.xlsx."""
import sys, os, json, base64
sys.stdout.reconfigure(encoding='utf-8')
BASE = next((p for p in ['/home/rabasoff/crm-master', r'D:\ИИ\CRM_Мастерская'] if os.path.exists(os.path.join(p, 'app.py'))), '.')
sys.path.insert(0, BASE)
from app import app
from models import db, PlanProduction

DATA = json.loads(base64.b64decode('').decode('utf-8'))

def _exists(code, date, wo):
    q = PlanProduction.query.filter_by(article_code=code, prod_date=date)
    if wo:
        q = q.filter_by(work_order=wo)
    else:
        q = q.filter(PlanProduction.work_order.is_(None))
    return q.first() is not None

with app.app_context():
    from datetime import date as _d
    made = skipped = 0
    for r in DATA['eoy']:
        d = _d(*map(int, r['date'].split('-')))
        if _exists(r['code'], d, ''):
            skipped += 1
            continue
        db.session.add(PlanProduction(article_code=r['code'], article_name=r['name'],
                                      qty=r['qty'], unit=r['unit'], prod_date=d,
                                      status='planned'))
        made += 1
    for r in DATA['wo']:
        d = _d(*map(int, r['date'].split('-')))
        if _exists(r['code'], d, r['work_order'] or None):
            skipped += 1
            continue
        notes = ('UVD: ' + r['uvd']) if r.get('uvd') else ''
        db.session.add(PlanProduction(article_code=r['code'], article_name=r['name'],
                                      qty=r['qty'], unit=r['unit'], prod_date=d,
                                      work_order=r.get('work_order') or None,
                                      lot=r.get('lot') or None,
                                      machine_name=r.get('machine') or None,
                                      notes=notes, status='planned'))
        made += 1
    db.session.commit()
    total = PlanProduction.query.count()
    print(f'IMPORT: created={made} skipped={skipped} total_plan_production={total}')
